#include <iostream>
#include <string>
#include <algorithm>
#include <cmath>

int main() {
    int h, n;
    std::cin >> h >> n;
    int n_minus_one = n - 1;
    std::string N = std::bitset<32>(n_minus_one).to_string();
    N = N.substr(32 - std::to_string(n_minus_one).length());
    N = std::string(h - N.length(), '0') + N;
    int ans = 0;
    bool f = false;
    for (int i = 0; i < h; ++i) {
        if (N[i] != (f ? '0' : '1')) {
            f = !f;
            ans += 1;
        } else {
            ans += (int)std::pow(2, h - i - 1);
        }
    }
    std::cout << ans << std::endl;
    return 0;
}
